    err=bpf_prog_attach(parse_prog,map_fd_break,BPF_SK_SKB_STREAM_PARSER,0); if err==0{printf(c!("Allowed attaching SK_SKB program to invalid map\n"));goto_sockmap(&mut sfd,fd,map_fd_tx,map_fd_rx);} err=bpf_prog_attach(parse_prog,map_fd_rx,BPF_SK_SKB_STREAM_PARSER,0); if err!=0{printf(c!("Failed stream parser bpf prog attach\n"));goto_sockmap(&mut sfd,fd,map_fd_tx,map_fd_rx);} err=bpf_prog_attach(verdict_prog,map_fd_rx,BPF_SK_SKB_STREAM_VERDICT,0); if err!=0{printf(c!("Failed stream verdict bpf prog attach\n"));goto_sockmap(&mut sfd,fd,map_fd_tx,map_fd_rx);} err=bpf_prog_attach(msg_prog,map_fd_msg,BPF_SK_MSG_VERDICT,0); if err!=0{printf(c!("Failed msg verdict bpf prog attach\n"));goto_sockmap(&mut sfd,fd,map_fd_tx,map_fd_rx);} err=bpf_prog_attach(verdict_prog,map_fd_rx,__MAX_BPF_ATTACH_TYPE,0); if err==0{printf(c!("Attached unknown bpf prog\n"));goto_sockmap(&mut sfd,fd,map_fd_tx,map_fd_rx);}
    for j in 2..6{let jj=j as c_int; err=bpf_map_update_elem(map_fd_rx,ptr(&jj),ptr(&sfd[j]),BPF_ANY); if err!=0{printf(c!("Failed map_fd_rx update sockmap %i '%i:%i'\n"),err,j,sfd[j]);goto_sockmap(&mut sfd,fd,map_fd_tx,map_fd_rx);} err=bpf_map_update_elem(map_fd_tx,ptr(&jj),ptr(&sfd[j]),BPF_ANY); if err!=0{printf(c!("Failed map_fd_tx update sockmap %i '%i:%i'\n"),err,j,sfd[j]);goto_sockmap(&mut sfd,fd,map_fd_tx,map_fd_rx);}}
    for j in 2..4{let jj=j as c_int; err=bpf_map_delete_elem(map_fd_rx,ptr(&jj)); if err!=0{printf(c!("Failed delete sockmap rx %i '%i:%i'\n"),err,j,sfd[j]);goto_sockmap(&mut sfd,fd,map_fd_tx,map_fd_rx);} err=bpf_map_delete_elem(map_fd_tx,ptr(&jj)); if err!=0{printf(c!("Failed delete sockmap tx %i '%i:%i'\n"),err,j,sfd[j]);goto_sockmap(&mut sfd,fd,map_fd_tx,map_fd_rx);}}
